package com.ssk.kiosk.service;import com.ssk.kiosk.dto.*;import com.ssk.kiosk.model.*;import com.ssk.kiosk.repo.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.security.SecureRandom;import java.time.*;import java.util.*;@Service @RequiredArgsConstructor public class GatePassService{private final VisitApplicationRepository apps;private final CheckInOutEventRepository events;private final AuditLogRepository audit;private static final SecureRandom R=new SecureRandom();@Transactional public ApplicationResponse create(ApplicationRequest r){VisitApplication a=new VisitApplication();a.setApplicationNumber("APP-"+Instant.now().toEpochMilli());a.setFullName(r.fullName());a.setCategoryCode(r.categoryCode());a.setDocumentType(r.documentType());a.setMaskedDocumentNumber(mask(r.documentNumber()));a.setCompanyName(r.companyName());a.setHostEmployeeId(r.hostEmployeeId());a.setVisitPurpose(r.visitPurpose());a.setLocationName(r.locationName());a.setGateName(r.gateName());a.setValidFrom(r.validFrom());a.setValidUntil(r.validUntil());a.setPhotoPath(r.photoPath());a.setQrToken(token());a.setStatus(r.categoryCode().equalsIgnoreCase("VISITOR")?ApplicationStatus.APPROVED:ApplicationStatus.PENDING_HOST_APPROVAL);apps.save(a);log("kiosk","SUBMIT",a.getId(),"Application submitted");return map(a);} public ValidationResponse validate(ValidateRequest r){VisitApplication a=apps.findByQrToken(r.tokenOrPassNumber()).or(()->apps.findByApplicationNumber(r.tokenOrPassNumber())).orElse(null);if(a==null)return new ValidationResponse(false,"INVALID","Pass not found",null);if(a.getValidUntil().isBefore(Instant.now()))return new ValidationResponse(false,"EXPIRED","Pass has expired",map(a));boolean ok=a.getStatus()==ApplicationStatus.APPROVED||a.getStatus()==ApplicationStatus.CHECKED_IN;return new ValidationResponse(ok,a.getStatus().name(),ok?"Pass is valid":"Pass is not valid for entry",map(a));} @Transactional public ApplicationResponse checkIn(UUID id,CheckRequest r){VisitApplication a=apps.findById(id).orElseThrow();if(a.getValidUntil().isBefore(Instant.now()))throw new IllegalStateException("Pass expired");if(a.getStatus()!=ApplicationStatus.APPROVED)throw new IllegalStateException("Pass is not approved or already checked in");a.setStatus(ApplicationStatus.CHECKED_IN);event(a,"CHECK_IN",r);return map(a);}@Transactional public ApplicationResponse checkOut(UUID id,CheckRequest r){VisitApplication a=apps.findById(id).orElseThrow();if(a.getStatus()!=ApplicationStatus.CHECKED_IN)throw new IllegalStateException("Cannot check out before check in");a.setStatus(ApplicationStatus.CHECKED_OUT);event(a,"CHECK_OUT",r);return map(a);} private void event(VisitApplication a,String t,CheckRequest r){CheckInOutEvent e=new CheckInOutEvent();e.setPassId(a.getId());e.setEventType(t);e.setGateName(r.gateName());e.setTerminal(r.terminal());e.setRemarks(r.remarks());events.save(e);log("security",t,a.getId(),r.remarks());} private void log(String actor,String action,UUID id,String rem){AuditLog l=new AuditLog();l.setActor(actor);l.setAction(action);l.setEntityType("VisitApplication");l.setEntityId(id.toString());l.setRemarks(rem);audit.save(l);} private static String token(){byte[]b=new byte[24];R.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} private static String mask(String s){return s==null?null:"****"+s.substring(Math.max(0,s.length()-4));} public static ApplicationResponse map(VisitApplication a){return new ApplicationResponse(a.getId(),a.getApplicationNumber(),a.getApplicationNumber(),a.getQrToken(),a.getFullName(),a.getStatus().name(),a.getMaskedDocumentNumber(),a.getValidFrom(),a.getValidUntil());}}
